import 'package:flutter/material.dart';import '../../../core/network/football_repository.dart';
class PlayerCompareScreen extends StatefulWidget{const PlayerCompareScreen({super.key,required this.playerA,required this.playerB});final int playerA,playerB;@override State<PlayerCompareScreen> createState()=>_PlayerCompareScreenState();}
class _PlayerCompareScreenState extends State<PlayerCompareScreen>{final repo=FootballRepository();late Future<Map<String,dynamic>> future;@override void initState(){super.initState();future=repo.comparePlayers(widget.playerA,widget.playerB);}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Player Comparison')),body:FutureBuilder<Map<String,dynamic>>(future:future,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!;final a=d['player_a']??{},b=d['player_b']??{};final rows=List<dynamic>.from(d['comparison']??[]);return ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:_player(a)),const Padding(padding:EdgeInsets.all(12),child:Text('VS')),Expanded(child:_player(b))]),const SizedBox(height:12),...rows.map((r)=>Card(child:ListTile(title:Text('${r['metric']}'),leading:Text('${r['a']??'-'}'),trailing:Text('${r['b']??'-'}'))))]);}),);Widget _player(dynamic p)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[const Icon(Icons.person,size:42),Text('${p['name']??''}',textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.bold))])));}
